create table if not exists public.hero_slides (id bigint generated by default as identity primary key,badge text not null default '',title text not null default '',description text default '',button_text text default '',button_link text default '#catalogue',secondary_action text default 'whatsapp',secondary_text text default '',secondary_link text default '',trust text default '',mini_one text default '',mini_two text default '',image_url text,sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant select on public.hero_slides to anon,authenticated;
grant insert,update,delete on public.hero_slides to authenticated;
alter table public.hero_slides enable row level security;
drop policy if exists "hero_public_read_active" on public.hero_slides;
drop policy if exists "hero_admin_read" on public.hero_slides;
drop policy if exists "hero_admin_insert" on public.hero_slides;
drop policy if exists "hero_admin_update" on public.hero_slides;
drop policy if exists "hero_admin_delete" on public.hero_slides;
create policy "hero_public_read_active" on public.hero_slides for select to anon using (active=true);
create policy "hero_admin_read" on public.hero_slides for select to authenticated using (auth.uid()='7e974a6a-51e5-449a-b115-71207df79d24');
create policy "hero_admin_insert" on public.hero_slides for insert to authenticated with check (auth.uid()='7e974a6a-51e5-449a-b115-71207df79d24');
create policy "hero_admin_update" on public.hero_slides for update to authenticated using (auth.uid()='7e974a6a-51e5-449a-b115-71207df79d24') with check (auth.uid()='7e974a6a-51e5-449a-b115-71207df79d24');
create policy "hero_admin_delete" on public.hero_slides for delete to authenticated using (auth.uid()='7e974a6a-51e5-449a-b115-71207df79d24');
